package com.yuegang.zhihui.notification.application;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.notification.api.*;import java.time.*;import java.util.*;import java.util.regex.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public class NotificationService{private static final Pattern TOKEN=Pattern.compile("\\{\\{([A-Za-z][A-Za-z0-9_]{0,63})}}");private final JdbcTemplate jdbc;private final ObjectMapper json=new ObjectMapper();public NotificationService(DataSource d){jdbc=new JdbcTemplate(d);}@Transactional public NotificationView create(NotificationCommand c){long user=id(c.userId());NotificationView exists=jdbc.query("SELECT id,title,content,status,read_at,created_at FROM notification_message WHERE event_id=? AND user_id=?",r->r.next()?view(r):null,c.eventId(),user);if(exists!=null)return exists;var t=jdbc.query("SELECT title_template,content_template FROM notification_template WHERE code=? AND enabled=TRUE",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new String[]{r.getString(1),r.getString(2)};},c.templateCode());long message=next();jdbc.update("INSERT INTO notification_message(id,event_id,user_id,template_code,title,content,status,next_retry_at) VALUES(?,?,?,?,?,?,'PENDING',NOW(6))",message,c.eventId(),user,c.templateCode(),render(t[0],c.variables()),render(t[1],c.variables()));audit(message,"CREATED",null,null);return get(message);}@Transactional public int dispatchPending(){var ids=jdbc.queryForList("SELECT id FROM notification_message WHERE status IN('PENDING','RETRY') AND (next_retry_at IS NULL OR next_retry_at<=NOW(6)) ORDER BY created_at LIMIT 50",Long.class);int sent=0;for(long message:ids){try{if(jdbc.update("UPDATE notification_message SET status='SENT',sent_at=NOW(6),next_retry_at=NULL,last_error=NULL WHERE id=? AND status IN('PENDING','RETRY')",message)==1){audit(message,"SENT",null,null);sent++;}}catch(RuntimeException e){fail(message,e.getMessage());}}return sent;}@Transactional public void fail(long message,String reason){Integer retries=jdbc.query("SELECT retry_count FROM notification_message WHERE id=?",r->r.next()?r.getInt(1):null,message);if(retries==null)return;if(retries>=4){jdbc.update("UPDATE notification_message SET status='DEAD',last_error=?,retry_count=retry_count+1,next_retry_at=NULL WHERE id=?",safe(reason),message);var data=jdbc.queryForMap("SELECT event_id,user_id,template_code,title,content FROM notification_message WHERE id=?",message);jdbc.update("INSERT IGNORE INTO notification_dead_letter(id,message_id,event_id,failure_reason,payload_json) VALUES(?,?,?,?,?)",next(),message,data.get("event_id"),safe(reason),write(data));audit(message,"DEAD_LETTER",null,safe(reason));}else{long delay=1L<<retries;jdbc.update("UPDATE notification_message SET status='RETRY',retry_count=retry_count+1,last_error=?,next_retry_at=DATE_ADD(NOW(6),INTERVAL ? MINUTE) WHERE id=?",safe(reason),delay,message);audit(message,"RETRY",null,safe(reason));}}public List<NotificationDeadLetterView>deadLetters(){return jdbc.query("SELECT id,message_id,event_id,failure_reason,failed_at FROM notification_dead_letter ORDER BY failed_at DESC LIMIT 200",(r,n)->new NotificationDeadLetterView(Long.toString(r.getLong(1)),Long.toString(r.getLong(2)),r.getString(3),r.getString(4),r.getTimestamp(5).toLocalDateTime().atOffset(ZoneOffset.UTC)));}@Transactional public void replay(String deadId,long operator){long did=id(deadId);Long message=jdbc.query("SELECT message_id FROM notification_dead_letter WHERE id=?",r->r.next()?r.getLong(1):null,did);if(message==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("UPDATE notification_message SET status='PENDING',retry_count=0,next_retry_at=NOW(6),last_error=NULL WHERE id=?",message);jdbc.update("DELETE FROM notification_dead_letter WHERE id=?",did);audit(message,"MANUAL_REPLAY",operator,null);}public List<NotificationView>list(long user){return jdbc.query("SELECT id,title,content,status,read_at,created_at FROM notification_message WHERE user_id=? ORDER BY created_at DESC LIMIT 100",(r,n)->view(r),user);}public void read(long user,String id){if(jdbc.update("UPDATE notification_message SET read_at=COALESCE(read_at,NOW(6)) WHERE id=? AND user_id=?",id(id),user)!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);}private NotificationView get(long id){return jdbc.query("SELECT id,title,content,status,read_at,created_at FROM notification_message WHERE id=?",r->{r.next();return view(r);},id);}private void audit(long message,String action,Long operator,String detail){jdbc.update("INSERT INTO notification_delivery_audit(id,message_id,action,operator_user_id,detail) VALUES(?,?,?,?,?)",next(),message,action,operator,detail);}private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private static String safe(String x){return x==null?"unknown":x.substring(0,Math.min(1000,x.length()));}private static String render(String t,Map<String,String>v){var m=TOKEN.matcher(t);var b=new StringBuilder();while(m.find()){String value=v.get(m.group(1));if(value==null)throw new BusinessException(ErrorCode.VALIDATION_ERROR);m.appendReplacement(b,Matcher.quoteReplacement(value));}m.appendTail(b);return b.toString();}private static NotificationView view(java.sql.ResultSet r)throws java.sql.SQLException{return new NotificationView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getString(4),r.getTimestamp(5)!=null,r.getTimestamp(6).toLocalDateTime().atOffset(ZoneOffset.UTC));}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String s){try{return Long.parseLong(s);}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
